    mul.lo.s32 %r12, %r7, %r8;       // base_col (CTA*16)
    shl.b32 %r13, %r5, 4;
    add.s32 %r13, %r13, %r9;         // tid_lin = ty*16+tx  (idx0)
    add.s32 %r14, %r13, 256;         // idx1
    mov.u32 %r15, smA;               // smA base address
    mov.u32 %r16, smB;               // smB base address
    mov.f32 %f1, 0f00000000;         // accumulator
    mov.u32 %r17, 0;                 // kk loop var
