    setp.lt.s32 %p3, %r21, %r2;
    and.pred %p4, %p2, %p3;
    mov.f32 %f2, 0f00000000;
    @!%p4 bra A_SKIP0;
    mad.lo.s32 %r22, %r20, %r2, %r21;
    mul.wide.s32 %rd4, %r22, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];
