    and.b32 %r25, %r14, 31;
    add.s32 %r26, %r11, %r24;
    add.s32 %r27, %r17, %r25;
    setp.lt.s32 %p5, %r26, %r1;
    setp.lt.s32 %p6, %r27, %r2;
    and.pred %p7, %p5, %p6;
    mov.f32 %f3, 0f00000000;
    @!%p7 bra A_SKIP1;
    mad.lo.s32 %r28, %r26, %r2, %r27;
    mul.wide.s32 %rd6, %r28, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f3, [%rd7];
