    shl.b32 %r29, %r14, 2;
    add.s32 %r29, %r29, %r15;
    st.shared.f32 [%r29], %f3;
    // ---- Load B tile element idx0 (cooperative, reused across BLOCK_Y threads) ----
    shr.u32 %r30, %r13, 4;           // k_in_tile0
    and.b32 %r31, %r13, 15;          // col_in_tile0
    add.s32 %r32, %r17, %r30;        // global k0
    add.s32 %r33, %r12, %r31;        // global col0
    setp.lt.s32 %p8, %r32, %r2;
    setp.lt.s32 %p9, %r33, %r1;
    and.pred %p10, %p8, %p9;
    mov.f32 %f4, 0f00000000;
    @!%p10 bra B_SKIP0;
    mad.lo.s32 %r34, %r32, %r1, %r33;
    mul.wide.s32 %rd8, %r34, 4;
    add.s64 %rd9, %rd2, %rd8;
    ld.global.f32 %f4, [%rd9];
