    shl.b32 %r35, %r13, 2;
    add.s32 %r35, %r35, %r16;
    st.shared.f32 [%r35], %f4;
    // ---- Load B tile element idx1 ----
    shr.u32 %r36, %r14, 4;
    and.b32 %r37, %r14, 15;
    add.s32 %r38, %r17, %r36;
    add.s32 %r39, %r12, %r37;
    setp.lt.s32 %p11, %r38, %r2;
    setp.lt.s32 %p12, %r39, %r1;
    and.pred %p13, %p11, %p12;
    mov.f32 %f5, 0f00000000;
    @!%p13 bra B_SKIP1;
    mad.lo.s32 %r40, %r38, %r1, %r39;
    mul.wide.s32 %rd10, %r40, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f5, [%rd11];
