    shl.b32 %r41, %r14, 2;
    add.s32 %r41, %r41, %r16;
    st.shared.f32 [%r41], %f5;
    bar.sync 0;
    // ---- Compute partial dot product using shared tiles ----
    mov.u32 %r42, 0;                 // kt
