    shl.b32 %r44, %r43, 2;
    add.s32 %r44, %r44, %r15;
    ld.shared.f32 %f6, [%r44];
    mad.lo.s32 %r45, %r42, 16, %r9;  // smB offset (elems) = kt*16+tx
    shl.b32 %r46, %r45, 2;
    add.s32 %r46, %r46, %r16;
    ld.shared.f32 %f7, [%r46];
    fma.rn.f32 %f1, %f6, %f7, %f1;
    add.s32 %r42, %r42, 1;
    bra COMPUTE_LOOP;
