    setp.lt.s32 %p16, %r10, %r1;
    and.pred %p17, %p15, %p16;
    @!%p17 bra DONE;
    mad.lo.s32 %r47, %r6, %r1, %r10;   // c_idx = row*M+col
    mul.wide.s32 %rd12, %r47, 4;
    add.s64 %rd13, %rd3, %rd12;
    st.global.f32 [%rd13], %f1;
